const $=id=>document.getElementById(id), money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults={mpg:6.5,maintenance:.20,driver:0,overhead:75,art:0,dispatch:0,factoring:0,target:1};
function read(k,f){try{return JSON.parse(localStorage.getItem(k))||f}catch{return f}}let profile={...defaults,...read('sagi-profile',{})},saved=read('sagi-trips',[]),history=[],last=null;
function persist(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('Storage unavailable. Export your estimate before leaving.');return false}}
function toast(s){$('toast').textContent=s;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3500)}
function tab(id){document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==id);document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===id));if(id==='saved')renderSaved();if(id==='lanes')renderLanes();if(id==='connections'&&window.renderFuel)window.renderFuel();if(id==='ratecons'&&window.renderRatecons)window.renderRatecons();window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>tab(b.dataset.go));
const fields=[['mpg','Fuel economy (miles / US gallon)',.1],['maintenance','Maintenance reserve ($/mile)',0],['driver','Driver pay ($/mile)',0],['overhead','Fixed overhead ($/day)',0],['art','SST / ART deduction (%)',0],['dispatch','Dispatch (%)',0],['factoring','Factoring (%)',0],['target','Target earnings ($/all miles)',0]];
$('settingFields').innerHTML=fields.map(([id,label,min])=>`<label>${label}<input id="s_${id}" type="number" min="${min}" step="0.01" value="${profile[id]}" required></label>`).join('');
function updateProfile(){$('profileSummary').textContent=`${profile.mpg} MPG · ${money(profile.maintenance)}/mile maintenance · ${money(profile.overhead)}/day overhead`;}updateProfile();
$('settingsForm').onsubmit=e=>{e.preventDefault();const p={};fields.forEach(([id])=>p[id]=Number($('s_'+id).value));if(p.art+p.dispatch+p.factoring>=100){toast('Combined percentage deductions must be below 100%.');return}profile=p;if(persist('sagi-profile',profile))$('settingsStatus').textContent='Saved on this device.';updateProfile();if(last)calculate()};
function tripMath(t,p){const miles=t.miles+t.deadhead, gallons=miles/p.mpg, fuel=gallons*t.price,maint=miles*p.maintenance,driver=miles*p.driver,overhead=t.days*p.overhead,rate=(p.art+p.dispatch+p.factoring)/100,base=fuel+maint+driver+overhead+t.tolls+t.extras+t.fees,deductions=t.pay*rate,cost=base+deductions,net=t.pay-cost;return{miles,gallons,fuel,maint,driver,overhead,deductions,cost,net,netMile:net/miles,breakEven:base/(1-rate),targetRate:(base+p.target*miles)/(1-rate)}}
function calculate(){if(!$('tripForm').checkValidity()){last=null;$('result').innerHTML='<h2>Finish your trip details.</h2><p>Enter valid values to update this estimate.</p>';return;}const t={};['origin','destination'].forEach(k=>t[k]=$(k).value.trim());['pay','miles','deadhead','days','price','tolls','extras','fees'].forEach(k=>t[k]=Number($(k).value));if(!t.origin||!t.destination)return;const r=tripMath(t,profile);last={...t,...r,loadedMiles:t.miles,profile:{...profile},date:new Date().toISOString()};const rows=[['Fuel · '+r.gallons.toFixed(1)+' gal',r.fuel],['Maintenance reserve',r.maint],['Driver pay',r.driver],['Fixed overhead',r.overhead],['SST/ART + dispatch + factoring',r.deductions],['Tolls, trip fees & other',t.tolls+t.fees+t.extras]];
$('result').innerHTML=`<span class="eyebrow">ESTIMATED EARNINGS · BEFORE INCOME TAX</span><div class="amount">${money(r.net)}</div><small>From ${money(t.pay)} in load pay</small><div class="metrics"><div><b>${money(r.cost)}</b><small>Total estimated cost</small></div><div><b>${money(r.netMile)}</b><small>Earnings / all miles</small></div></div><div class="breakdown">${rows.map(([label,v])=>`<div class="row"><span>${label}</span><b>${money(v)}</b></div>`).join('')}</div><div class="goal"><b>${r.netMile>=profile.target?'Meets your earnings target':'Below your earnings target'}</b><br>Ask for at least ${money(r.targetRate)} to keep ${money(profile.target)}/mile.<br><small>Break-even load pay: ${money(r.breakEven)} · ${r.miles.toLocaleString()} total miles</small></div><p>Based on your inputs. Includes consumed fuel cost, not just today's fuel purchase. Unentered costs and IFTA settlement are excluded.</p><button id="saveTrip">Save this estimate</button>`;$('saveTrip').onclick=()=>{saved.unshift({...last,id:crypto.randomUUID(),rateconId:window.activeRateconId||null});if(persist('sagi-trips',saved))toast('Estimate saved on this device.');};}
$('tripForm').onsubmit=e=>{e.preventDefault();calculate();if(innerWidth<790)$('result').scrollIntoView({behavior:'smooth',block:'center'})};$('tripForm').oninput=()=>{if(last)calculate()};
$('example').onclick=()=>{window.setActiveRatecon?.(null);Object.entries({origin:'Crossville, TN',destination:'Lakeland, FL',pay:2200,miles:700,deadhead:50,days:2,price:3.50,tolls:25,extras:20,fees:0}).forEach(([k,v])=>$(k).value=v);calculate();toast('Sample load loaded. Review all assumptions.');};
fetch('history.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{history=d;$('laneIntro').textContent=d.length?`${d.length} historical trip records. Reuse a route, then confirm today's miles and rate.`:'Your saved trip estimates can be reused from Saved trips. No private historical records are included in this edition.';renderLanes()}).catch(()=>$('laneList').textContent='Could not load historical trips. Please reload.');
function renderLanes(){const q=$('search').value.toLowerCase();const lanes=history.length?history:saved.map(s=>({from:s.origin,to:s.destination,pay:s.pay,miles:s.loadedMiles??(s.miles-s.deadhead),fuel:s.fuel,year:new Date(s.date).getFullYear()}));$('laneIntro').textContent=lanes.length?`${lanes.length} saved routes. Reuse a route, then confirm today's miles and rate.`:'Save your first trip estimate to build your personal route library.';$('laneList').innerHTML=lanes.map((h,i)=>({...h,i})).filter(h=>(h.from+' '+h.to).toLowerCase().includes(q)).map(h=>`<div class="lane"><div><b>${esc(h.from)} → ${esc(h.to)}</b><small>${h.year} record · ${money(h.pay)} historical pay · ${h.miles?h.miles+' miles':'Mileage missing'}${!h.fuel?' · Fuel missing':''}</small></div><button data-lane="${h.i}">Use route</button></div>`).join('')||'<p>No saved routes yet, or no routes match your search. Save an estimate from Plan a trip to get started.</p>';$('laneList').querySelectorAll('button').forEach(b=>b.onclick=()=>{const h=lanes[Number(b.dataset.lane)];window.setActiveRatecon?.(null);$('tripForm').reset();$('origin').value=h.from;$('destination').value=h.to;$('pay').value=h.pay;$('miles').value=h.miles||'';last=null;$('result').innerHTML='<h2>Historical route loaded.</h2><p>Confirm mileage, current load pay, fuel price and trip expenses, then calculate.</p>';tab('plan');});}$('search').oninput=renderLanes;
$('fuelFields').innerHTML=['A','B'].map(k=>`<div><h3>Stop ${k}</h3><label>Station / location<input id="f${k}name" placeholder="Enter station" required></label>${[['price','Pump price ($/gal)'],['discount','Your discount ($/gal)'],['tax','Refundable tax ($/gal)'],['detour','Extra round-trip miles']].map(([id,label])=>`<label>${label}<input id="f${k}${id}" type="number" min="0" step="0.001" ${id==='price'?'placeholder="Current quote"':'value="0"'} required></label>`).join('')}</div>`).join('');
$('fuelForm').onsubmit=e=>{e.preventDefault();const gal=+$('gallons').value;let stops=[];for(const k of ['A','B']){const n=id=>+$('f'+k+id).value, pump=n('price')-n('discount'),net=pump-n('tax');if(net<0){toast('Discount plus refundable tax cannot exceed pump price.');return}const detour=n('detour')*(pump/profile.mpg+profile.maintenance+profile.driver);stops.push({name:$('f'+k+'name').value,net,cash:gal*pump,effective:gal*net+detour,detour});}stops.sort((a,b)=>a.effective-b.effective);$('fuelResult').innerHTML=`<h3>${Math.abs(stops[1].effective-stops[0].effective)<.005?'Both stops have the same modeled cost':esc(stops[0].name)+' has the lower modeled cost'}</h3><b>${money(stops[1].effective-stops[0].effective)} difference</b>${stops.map(s=>`<div class="note"><b>${esc(s.name)}</b>Pump purchase: ${money(s.cash)}<br>Net fuel price: ${money(s.net)}/gal<br>Estimated detour cost: ${money(s.detour)}<br>Net purchase + detour: ${money(s.effective)}</div>`).join('')}<small>Tax refunds are not immediate pump savings. Verify eligibility and route accessibility before choosing a stop.</small>`;};
